import{_ as e,o as t,c as i,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"JIT / Tiered Compilation / V8 TurboFan / Cranelift","description":"","frontmatter":{},"headers":[],"relativePath":"compilers/codegen/jit.md","filePath":"compilers/codegen/jit.md","lastUpdated":1788475713000}'),n={name:"compilers/codegen/jit.md"};function o(l,a,r,p,d,c){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="jit-tiered-compilation-v8-turbofan-cranelift" tabindex="-1">JIT / Tiered Compilation / V8 TurboFan / Cranelift <a class="header-anchor" href="#jit-tiered-compilation-v8-turbofan-cranelift" aria-label="Permalink to &quot;JIT / Tiered Compilation / V8 TurboFan / Cranelift&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>JIT 编译器在<strong>运行时</strong>把字节码（或源码）翻译成机器码，热路径深度优化、冷路径保留解释器执行。<strong>Tiered Compilation</strong> 把这条流水线分多层：最开始解释器（Ignition、HotSpot 解释器、PyPy 解释器）零编译、~10-100x 慢；快速编出基线机器码（V8 Sparkplug、HotSpot C1）做 1x 接近 AOT；最热的代码用激进优化器（V8 TurboFan、HotSpot C2）做到 LLVM <code>-O2</code> 级甚至更优——因为有运行时 profile 可以做纯静态难以做到的 devirt、type feedback、speculative inlining。理解 V8、HotSpot、Cranelift、Julia、PyPy 的 tiered 模型与 deoptimization 机制是 JIT 现代化的入口。</p><hr><h2 id="一、jit-vs-aot-工程对比" tabindex="-1">一、JIT vs AOT 工程对比 <a class="header-anchor" href="#一、jit-vs-aot-工程对比" aria-label="Permalink to &quot;一、JIT vs AOT 工程对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>AOT (LLVM/GCC)</th><th>JIT (V8/HotSpot/PyPy/Julia)</th></tr></thead><tbody><tr><td>启动</td><td>直接跑机器码</td><td>必须先解释 + 编译</td></tr><tr><td>峰值</td><td>LLVM <code>-O3</code> 接近上限</td><td>HotSpot C2 / V8 TurboFan 可超 LLVM</td></tr><tr><td>优化依据</td><td>静态分析 + PGO (人工采样)</td><td>运行时 profile 自动</td></tr><tr><td>解决 polymorphism</td><td>C++ devirt 模板、虚函数分析</td><td>V8 inline cache、HotSpot CHA</td></tr><tr><td>Binary 大小</td><td>原生二进制</td><td>字节码 + JIT cache</td></tr><tr><td>部署可重现</td><td>✅ 同输入同 binary</td><td>❌ JIT 受执行时 profile 影响</td></tr><tr><td>安全</td><td>编译产物可 audit</td><td>JIT compile 由地址必有 W^X 麻烦事故</td></tr></tbody></table><p>AOT 优势是<strong>首次执行快、可 reproducible、无 security concern</strong>。JIT 优势是<strong>因为 profile 在运行中收集、能做推测性优化 + 可 deopt → 实际峰值经常超 AOT</strong>。</p><hr><h2 id="二、tiered-compilation-设计" tabindex="-1">二、Tiered Compilation 设计 <a class="header-anchor" href="#二、tiered-compilation-设计" aria-label="Permalink to &quot;二、Tiered Compilation 设计&quot;">​</a></h2><h3 id="v8-js-5-tier-现代架构" tabindex="-1">V8 (JS) 5-tier 现代架构 <a class="header-anchor" href="#v8-js-5-tier-现代架构" aria-label="Permalink to &quot;V8 (JS) 5-tier 现代架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JavaScript source</span></span>
<span class="line"><span>  ↓ Parser</span></span>
<span class="line"><span>AST</span></span>
<span class="line"><span>  ↓ Ignition Compiler</span></span>
<span class="line"><span>Ignition bytecode</span></span>
<span class="line"><span>  ↓ interpret (initial)</span></span>
<span class="line"><span>hot bytecode → counter threshold</span></span>
<span class="line"><span>  ↓ Sparkplug (baseline JIT, fast compile)</span></span>
<span class="line"><span>fast baseline machine code</span></span>
<span class="line"><span>  ↓ hot further (counter)</span></span>
<span class="line"><span>TurboFan (Tier 1 optimizing)</span></span>
<span class="line"><span>  ↓ if polymorhism/re-checks fail</span></span>
<span class="line"><span>Maglev (Tier 2 mid-top optimizing)</span></span>
<span class="line"><span>  ↓ hottest methods</span></span>
<span class="line"><span>TurboFan (Tier 3 top, speculative + inlining)</span></span></code></pre></div><h3 id="hotspot-java-5-tier-编译" tabindex="-1">HotSpot (Java) 5-tier 编译 <a class="header-anchor" href="#hotspot-java-5-tier-编译" aria-label="Permalink to &quot;HotSpot (Java) 5-tier 编译&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0. 解释器</span></span>
<span class="line"><span>1. C1 with profiling</span></span>
<span class="line"><span>2. C1 without profiling   # cold code 编译了一次没有后续触发</span></span>
<span class="line"><span>3. C1 with profiling     # collect types + branches</span></span>
<span class="line"><span>4. C2 aggressive optimizing with profile</span></span></code></pre></div><p>HotSpot OSR (on-stack-replacement)、CHA (Class Hierarchy Analysis) + escape analysis + speculative devirt 让 C2 编出来的代码再 5-30% 超 GCC <code>-O3</code> 静态编。</p><h3 id="go-vs-rust-vs-python" tabindex="-1">Go vs Rust vs Python <a class="header-anchor" href="#go-vs-rust-vs-python" aria-label="Permalink to &quot;Go vs Rust vs Python&quot;">​</a></h3><ul><li><strong>Go</strong>: 默认 AOT (gc tool chain)，无 JIT。<code>gctrace</code> debug 模式可观察。</li><li><strong>Rust</strong>: AOT (LLVM backend)，Wasm 时 Cranelift 替代 LLVM 做 JIT 级速度。</li><li><strong>Python</strong>: CPython 解释器无 JIT（3.13 之前）；PyPy 有 JIT (RPython-based trace compilation)；3.13 起有 adaptive interpreter (specializing bytecode)，但不是 JIT。</li></ul><hr><h2 id="三、v8-turbofan-内幕" tabindex="-1">三、V8 TurboFan 内幕 <a class="header-anchor" href="#三、v8-turbofan-内幕" aria-label="Permalink to &quot;三、V8 TurboFan 内幕&quot;">​</a></h2><h3 id="sea-of-nodes-ir" tabindex="-1">Sea-of-Nodes IR <a class="header-anchor" href="#sea-of-nodes-ir" aria-label="Permalink to &quot;Sea-of-Nodes IR&quot;">​</a></h3><p>TurboFan 用 Cliff Click 1995 设计的 <strong>Sea-of-Nodes</strong> 表示：</p><ul><li>节点 = 操作 (<code>Add</code>, <code>Load</code>, <code>Phi</code>, <code>CheckMaps</code>, <code>Branch</code>...)</li><li>边 = 数据依赖 (输入值) 或 控制依赖 (control flow edge) 或 <strong>effect edge</strong> (内存副作用顺序)</li><li>是把 CFG 与 SSA 融合的&quot;图 IR&quot;——各节点自由调度，没显式 basic block 直到 schedule 阶段才把 Nodesort 进 block</li></ul><p>特殊在中<strong>有 Effect dependency edge</strong>：一条 <code>Store *p</code> 之后跟着 <code>Load *q</code>，编译器把 q 与 p 用 effect edge 串起来——除非 alias analysis 证明无关系。</p><h3 id="type-feedback-vector-ics" tabindex="-1">Type Feedback Vector (ICs) <a class="header-anchor" href="#type-feedback-vector-ics" aria-label="Permalink to &quot;Type Feedback Vector (ICs)&quot;">​</a></h3><p>V8 在 Ignition 执行每条字节码时记<strong>类型历史</strong>:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// IC slot: (Smi, Smi) → Smi+</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// IC slot: (HeapNum, Smi) → Num+ (unbox float)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// IC slot: (String, String) → String+</span></span></code></pre></div><p>每条操作有 <strong>inline cache</strong> (IC)：第一次跑时探测类型 + 选择 specialization, 后续命中直接走 specul code。多态 (<code>polymorphic</code>) 时 IC vs monomorphic 大幅差性能。</p><p>TurboFan 优化时 query IC，得到代表类型，编译生成只看一种形态的指令 + <strong>deopt guard</strong>——若运行时类型 deviate，bailout 回 Ignition。</p><h3 id="speculative-inlining" tabindex="-1">Speculative Inlining <a class="header-anchor" href="#speculative-inlining" aria-label="Permalink to &quot;Speculative Inlining&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> g</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); }</span></span></code></pre></div><p><code>x.f()</code> 可调用 100 个不同类，静态分析不可 inline。但 profile 显示 99% 调用对单一类型 <code>A.f</code> → TurboFan specul devirt + emit:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CheckMaps x, A_map</span></span>
<span class="line"><span>call A.f</span></span>
<span class="line"><span>guard not taken: deopt to interpreter at frame index N</span></span></code></pre></div><p>热 path 跑 devirt，0.1% path 走 guard 失败回退。HotSpot 称为 <strong>speculative devirtualization</strong>。</p><h3 id="deoptimization-deopt" tabindex="-1">Deoptimization (Deopt) <a class="header-anchor" href="#deoptimization-deopt" aria-label="Permalink to &quot;Deoptimization (Deopt)&quot;">​</a></h3><p>V8 deopt 流程：</p><ol><li>Generated code 在每个 specul 假设的位置放 <strong>deopt guard</strong>: <code>cmp map(x), expected; jne deopt_pad</code></li><li>deopt_pad 调用 <code>Runtime_Deopt</code>：用 frame translation 信息恢复 Ignition 字节码状态 + 寄存器状态 (反推 SSA → 栈)</li><li>跳回 Ignition 的对应 bytecode offset 执行</li></ol><p>deopt 大量使用 <code>Maps</code>(隐藏类)、<code>FrameInfo</code>——LLVM 与 Cranelift 没这种&quot;反编译到 IR&quot; 机制，因为它们不假设持续执行。</p><h3 id="webassembly-在-v8" tabindex="-1">WebAssembly 在 V8 <a class="header-anchor" href="#webassembly-在-v8" aria-label="Permalink to &quot;WebAssembly 在 V8&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Wasm binary → Streaming Decoder</span></span>
<span class="line"><span>  → Liftoff (baseline JIT, fast compile)</span></span>
<span class="line"><span>  → TurboFan (optimizing when hot)</span></span></code></pre></div><p>Wasm binary 是 1) typed, 2) structured (no control flow irreducibility), 3) 无 polymorphism——比 JS 简单。<strong>Liftoff</strong> 编译快，<strong>TurboFan</strong> 给热函数再优化。Wasmer、Wasmtime (基于 Cranelift), GraalWasm 等都是类似 pipeline。</p><hr><h2 id="四、hotspot-c2" tabindex="-1">四、HotSpot C2 <a class="header-anchor" href="#四、hotspot-c2" aria-label="Permalink to &quot;四、HotSpot C2&quot;">​</a></h2><h3 id="ideal-graph" tabindex="-1">Ideal Graph <a class="header-anchor" href="#ideal-graph" aria-label="Permalink to &quot;Ideal Graph&quot;">​</a></h3><p>C2 的 IR 是 <strong>Ideal Graph</strong> (Sea-of-Nodes variant)——与 TurboFan 概念接近。Click 在 90 年代写 HotSpot 早期版本 (Strongtalk) 时发明的 Sea-of-Nodes。</p><h3 id="c2-的-phase" tabindex="-1">C2 的 Phase <a class="header-anchor" href="#c2-的-phase" aria-label="Permalink to &quot;C2 的 Phase&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Parse  (bytecode → Ideal Graph)</span></span>
<span class="line"><span>PhaseIdealLoop (loop tree、range check elimination)</span></span>
<span class="line"><span>PhaseIterGVN   (global value numbering)</span></span>
<span class="line"><span>PhaseIdealLoop (more)</span></span>
<span class="line"><span>PhaseIGVN</span></span>
<span class="line"><span>   ↓ (scheduler)</span></span>
<span class="line"><span>Macro Node expansion (alloc → scalar replace)</span></span>
<span class="line"><span>Matcher (selecting machine instructions, x86-64)</span></span>
<span class="line"><span>RegAlloc (Chaitin-PBQP)</span></span>
<span class="line"><span>emit</span></span></code></pre></div><h3 id="c2-做的-llvm-难做的优化" tabindex="-1">C2 做的 LLVM 难做的优化 <a class="header-anchor" href="#c2-做的-llvm-难做的优化" aria-label="Permalink to &quot;C2 做的 LLVM 难做的优化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优化</th><th>C2</th><th>LLVM AOT 等价</th></tr></thead><tbody><tr><td>推断虚函数 monomorphic</td><td>CHA + 类型 profile</td><td><code>-fdevirtualization</code> specul (有时)</td></tr><tr><td>scalar replace（escape analysis）</td><td>dead static elim</td><td>MemCpyOpt + alias analysis</td></tr><tr><td>biased locking</td><td>锁对象最近被同线程使用 → 测试 → 直接进入 — no atomic</td><td>无 (语言级无 monitor)</td></tr><tr><td>on-stack replacement</td><td>解释 → JIT 切换中 frame</td><td>无</td></tr><tr><td>range check elimination</td><td>loop bound profile 推断</td><td><code>-fcheck-new-roots</code> 不</td></tr></tbody></table><h3 id="重要副效应-jdk-17-deprecated-biased-locking" tabindex="-1">重要副效应：JDK 17 deprecated biased locking <a class="header-anchor" href="#重要副效应-jdk-17-deprecated-biased-locking" aria-label="Permalink to &quot;重要副效应：JDK 17 deprecated biased locking&quot;">​</a></h3><p>2021年 HotSpot 移除 biased locking —— 大量工程 benchmark 显示 它收益小、维护成本高。Safer <code>LockSupport</code> 兼容、JIT 仍可消除锁。</p><hr><h2 id="五、cranelift-wasm-时代的新-jit" tabindex="-1">五、Cranelift：Wasm 时代的新 JIT <a class="header-anchor" href="#五、cranelift-wasm-时代的新-jit" aria-label="Permalink to &quot;五、Cranelift：Wasm 时代的新 JIT&quot;">​</a></h2><p>Cranelift 是 Bytecode Alliance 的 Rust 编译器后端，为 Wasmtime、Wasm3、Firefox SpiderMonkey 后端提供 fast JIT 编译。</p><h3 id="设计" tabindex="-1">设计 <a class="header-anchor" href="#设计" aria-label="Permalink to &quot;设计&quot;">​</a></h3><ul><li><strong>CLIF (Cranelift IR)</strong>: SSA + typed + Sea-of-Nodes wind + ebb (extended basic block) 流</li><li><strong>Fast compile</strong>: 编译速度 ≈100MB/s, 3-20x 快于 LLVM 在 <code>-O0</code></li><li><strong>Quality</strong>: 接近 LLVM <code>-O1</code>, 不向量化激进</li><li><strong>Reg Alloc</strong>: Regalloc2 (graph coloring with splitting)</li><li><strong>Target</strong>: x86-64, ARM64, RISC-V64, s390x</li></ul><h3 id="用-llvm-process" tabindex="-1">用 LLVM Process <a class="header-anchor" href="#用-llvm-process" aria-label="Permalink to &quot;用 LLVM Process&quot;">​</a></h3><p>2023 起 Wasmtime 加 &quot;Cranelift + eBPF-style lazy optimization&quot;，目标是 1) 启动时基线快、2) 热点可后续 elevate 到 LLVM JIT。这就是 layered JIT——Cranelift 是基线，LLVM 是高阶。</p><h3 id="webassembly-component-model" tabindex="-1">WebAssembly Component Model <a class="header-anchor" href="#webassembly-component-model" aria-label="Permalink to &quot;WebAssembly Component Model&quot;">​</a></h3><p>Cranelift 与 WIT、Wasm 接口结合——Wasm component module 之间的 calls 通过 Cranelift 生成的 trampoline，无需重编 module，这是工业上 JIT 模块化的早期阶段。</p><hr><h2 id="六、pypy-trace-based-jit" tabindex="-1">六、PyPy Trace-based JIT <a class="header-anchor" href="#六、pypy-trace-based-jit" aria-label="Permalink to &quot;六、PyPy Trace-based JIT&quot;">​</a></h2><p>PyPy 用 <strong>trace-based JIT</strong> (Truffle 之外的另一种派别)，跟 method-based JIT (HotSpot) 不同：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 解释器跑循环 / 凄暖路径</span></span>
<span class="line"><span>2. trace recorder: 沿实际执行路径记录指令</span></span>
<span class="line"><span>3. 在 loop 辑后停下、组装成 loop 形式的 linear trace</span></span>
<span class="line"><span>4. optimize linear trace (constant propagation、loop peeling, inlining via trace stitching)</span></span>
<span class="line"><span>5. emit machine code (x86-64/ARM64/Z80 用)</span></span>
<span class="line"><span>6. Guard at start of trace: 类型匹配、循环上界等，否则 fail → fallback interpreter</span></span></code></pre></div><p>Trace-based 优势：<strong>loop-friendly 优化、linear 简单</strong>；劣势：分支多 + 迭代不规整时 trace 完整性下降。</p><h3 id="luajit-头部-trace-based-jit" tabindex="-1">LuaJIT 头部 trace-based JIT <a class="header-anchor" href="#luajit-头部-trace-based-jit" aria-label="Permalink to &quot;LuaJIT 头部 trace-based JIT&quot;">​</a></h3><p>LuaJIT (Mike Pall) 是业界最快 trace-based JIT 之一。LuaJIT trace 大部分是几 KB、quality 大致 = HotSpot C1。Mike 用大量手工汇编 trampoline。 <strong>异步 runtime</strong></p><hr><h2 id="七、jit-实施事故" tabindex="-1">七、JIT 实施事故 <a class="header-anchor" href="#七、jit-实施事故" aria-label="Permalink to &quot;七、JIT 实施事故&quot;">​</a></h2><h3 id="v8-speculative-devirt-大退步-2018" tabindex="-1">V8 Speculative Devirt 大退步 (2018) <a class="header-anchor" href="#v8-speculative-devirt-大退步-2018" aria-label="Permalink to &quot;V8 Speculative Devirt 大退步 (2018)&quot;">​</a></h3><p>Chrome 老版本 V8 &quot;BackgroundCompileThread&quot; 偶发 race 导致死锁——TurboFan deopt 后 re-compile 时丢失部分 IC，下次运行 0.5%-3% slower。Fix 用 ReadWriteLock。</p><h3 id="hotspot-reference-queue-overflow-1997" tabindex="-1">HotSpot Reference Queue Overflow (1997) <a class="header-anchor" href="#hotspot-reference-queue-overflow-1997" aria-label="Permalink to &quot;HotSpot Reference Queue Overflow (1997)&quot;">​</a></h3><p>旧 FullSpeed <code>ReferenceQueue</code> 在 GC 时可能丢软引用，导致 finalize 不调用揭晓的 bug。HotSpot 经典 bug fix &quot;Use precise reference discovery&quot;。</p><h3 id="native-image-容器-jit-memory-jit-cache-与-native-stack-冲突" tabindex="-1">Native Image 容器 JIT memory: JIT cache 与 native stack 冲突 <a class="header-anchor" href="#native-image-容器-jit-memory-jit-cache-与-native-stack-冲突" aria-label="Permalink to &quot;Native Image 容器 JIT memory: JIT cache 与 native stack 冲突&quot;">​</a></h3><p>Linux x86-64 第 47-bit memory limit：JIT cache 在 0x7fff... 高位、native stack 在低位 → unreachable mapping。一些 Cloud Foundry / WSL 1.x 环境导致 JVM crash。Native Image、JIT exec memory via <code>mmap</code> 在 sbrk 上同对策。</p><h3 id="eta-jit-cache-flush-apple-silicon-macos" tabindex="-1">ETA JIT Cache Flush (Apple Silicon macOS) <a class="header-anchor" href="#eta-jit-cache-flush-apple-silicon-macos" aria-label="Permalink to &quot;ETA JIT Cache Flush (Apple Silicon macOS)&quot;">​</a></h3><p>macOS Apple Silicon 下<strong>每个 W^X 必须 pmap_cs_</strong>* invalidate JTC cache、JIT 编译后 mmap PROT_EXEC—PROT_WRITE 翻转。<strong>JIT 在 Apple Silicon Mojave ~15-20% slower than x86_64 macOS</strong> 现 Apple thread_set_exception_ports 加 fast release — 解决。</p><h3 id="w-x-与-mmap-prot-exec" tabindex="-1">W^X 与 mmap PROT_EXEC <a class="header-anchor" href="#w-x-与-mmap-prot-exec" aria-label="Permalink to &quot;W^X 与 mmap PROT_EXEC&quot;">​</a></h3><p>很多 JIT 是感<code>mmap(..., PROT_READ|PROT_WRITE)</code> 写完代码 → <code>mprotect(PROT_READ|PROT_EXEC)</code> 启用 exec。 SPD Linux 中 CAP_SYS_RAWIO 起才有 — fix 经常 needs sysctl <code>kernel.randomize_va_space</code>、<code>vm.mmap_min_addr</code>。</p><h3 id="cranelift-bug-series-2020-2022" tabindex="-1">Cranelift Bug series (2020-2022) <a class="header-anchor" href="#cranelift-bug-series-2020-2022" aria-label="Permalink to &quot;Cranelift Bug series (2020-2022)&quot;">​</a></h3><p>Cranelift reg alloc 在某些 high-pressure 函数生成错误 spill slot → silent miscompile 一个 Wasm17_WASI 子模块 benchmark。回归测试定期 catch 。</p><hr><h2 id="八、jit-通过外部接口" tabindex="-1">八、JIT 通过外部接口 <a class="header-anchor" href="#八、jit-通过外部接口" aria-label="Permalink to &quot;八、JIT 通过外部接口&quot;">​</a></h2><h3 id="tier-hints" tabindex="-1">TIER HINTS <a class="header-anchor" href="#tier-hints" aria-label="Permalink to &quot;TIER HINTS&quot;">​</a></h3><p>HotSpot 把<strong>付费用户获取的 profile 经人工采样</strong> 摆到 AOT：AOT compile 用 <code>-XX:+PrintTieredEvents</code>, JIT 收集的 IC 与 hot loop dynamic run 编出 特定 AOT module so 更优生成代码。</p><p><strong>Project Leyden (Java)</strong> 把启动时代解释 + C1 编译收 移到 AOT，而运行时仍运行 C2 优化热路径。三分 系。</p><p><strong>GraalVM Native Image</strong> 把 HotSpot JIT 全推成 AOT — 不再有 JIT 在运行时 编译。Run-time 优惠: 低内存、启动快、镜像小。但峰值 slower than C2，无 trace.</p><h3 id="llvm-orc-jit" tabindex="-1">LLVM ORC JIT <a class="header-anchor" href="#llvm-orc-jit" aria-label="Permalink to &quot;LLVM ORC JIT&quot;">​</a></h3><p>LLVM 自带 ORC (On-Request Compilation) JIT API —— ClangRepl, Cling in ROOT6 用 LLVM JIT streaming during REPL runtime commands。Kits / engineering Kernels Jupyterling 等 REPL JIT 都用 ORC。</p><hr><h2 id="九、jit-vs-specul-side-effect-工程师视角" tabindex="-1">九、JIT vs Specul side effect 工程师视角 <a class="header-anchor" href="#九、jit-vs-specul-side-effect-工程师视角" aria-label="Permalink to &quot;九、JIT vs Specul side effect 工程师视角&quot;">​</a></h2><p>如果你写高性能 VM 服务：</p><ul><li><strong>热启动</strong>: V8/HotSpot tilt1 编 + 解释阶段时间长——通常 30s+ warm-up。注意 K8s rolling-deployment。</li><li><strong>Tiered flow peak</strong>：一般 50k-100k 触发 C2 编译—— 做 has 高 throughput 随机负载需要预 warm-up。</li><li><strong>Memory budget</strong>: JIT cache 通常 256-1GB 内存消耗。Hammerver 控 code cache size via <code>ReservedCodeCacheSize</code>、&quot;max JIT&quot;；</li><li><strong>可重现 build</strong>: JIT 受运行时环境影响——同样 binary、profile 影响运行时性能。常 forgot fixed performance benchmark 上 baseline dry-run 模式可能 不可比。</li><li><strong>Security</strong>: JIT exec memory 需 PROT_EXEC—让攻击面增加。<strong>Bugs in JIT</strong> (CVE-2018-) 是误 protect hole, <strong>Use-after-free in deopt path common</strong>.</li></ul><hr><h2 id="十、易错清单" tabindex="-1">十、易错清单 <a class="header-anchor" href="#十、易错清单" aria-label="Permalink to &quot;十、易错清单&quot;">​</a></h2><ol><li><strong>JIT run from cold start</strong>: 启动 benchmarking 1000 RPS 给 Go/Java 服务 超高 loadbalancer 上肯定 误。给 warm-up phase , measure 稳态 throughput。</li><li><strong>TieredCompilation disabled for benchmark</strong> 容易被忘记: JMH Java benchmark 默认 tiered；profile 全状态。</li><li><strong>Devirtualization guard 高估</strong>: 即使 specul devirt 后 90% dependency。若动态类型 fall outside IC 一直 changing (polymorphic call check map)，VIP 中 时间不会看 5-7 类型 STI TurboFan pass 设置 W.</li><li><strong>Forever keep JIT-cached code</strong>: W^X memory probs是 fixed-size, JIT <code>RT_FlushIC</code> 可能 default-Ignore。需 控制 reserve code size。</li><li><strong>LLVM ORC 不能完整 HotSpot C2</strong>: ORC 仅 supports AOT-level opt passes + lazily-compile module——不做 deopt、不做 speculative devirt。</li><li><strong>Wasmtime attrdeopt</strong>: Wasmtime 不做 Garbage collection, mem segfault (incl D lang) 无 JIT - silently going abort, limit MC trapping mechanism.</li></ol><hr><h2 id="十一、这一章带走的东西" tabindex="-1">十一、这一章带走的东西 <a class="header-anchor" href="#十一、这一章带走的东西" aria-label="Permalink to &quot;十一、这一章带走的东西&quot;">​</a></h2><ol><li>JIT 在运行时 compile, 用 profile 收集真实执行路径与类型信息——AOT 难做到。</li><li>Tiered Compilation 把解释器 (Ignition HotSpot强大的interpret)、Baseline JIT (Sparkplug C1) optimizing JIT (TurboFan C2) 串发明了启动与峰值的平衡。</li><li>V8 是 Sea-of-Nodes IR + Inline Cache Feedback + Speculative Deopt——与传统&quot;译成 AOT&quot; 完全不同。</li><li>HotSpot C2 用 Ideal Graph + escape analysis + CHA + biased locking, 跟 LLVM-O3 比 +5-30% spec-benchmarks.</li><li>Cranelift 走 &quot;fast compile first, hot code promote to LLVM later&quot;——Wasmtime、 Firefox SpiderMonkey 后端。</li><li>PyPy 是 trace-based JIT 与 method-based JIT (HotSpot / V8) 派别。</li><li>JIT run-time risk: profile volatility, code cache, security (PROT_EXEC/W^X), 与启动 warm-up cost 是 AOT 场景仍然 受欢迎原因。</li></ol><hr><p>下一节 → <a href="./../../distributed/">分布式系统总览</a></p>`,99)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
